var tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-tooletip="tooletip"]')),tooltipList=tooltipTriggerList.map(function(t){return new bootstrap.Tooltip(t)});const warningBtn=document.querySelector("#btn_warning");warningBtn.addEventListener("click",()=>{const t=document.querySelector("#alert");t.hasAttribute("style")?t.removeAttribute("style"):t.setAttribute("style","display:none")});const p=document.querySelector("#my_DoB");p.innerText=moment("20000209","YYYYMMDD").format("MMM Do Y");const formatDateBtn=document.querySelector("#formatDateBtn");formatDateBtn.addEventListener("click",()=>{const t=document.querySelector("#DoB_input").value.trim().toString().split(".").join(""),e=document.createElement("p");document.querySelector(".form").appendChild(e).innerText=`${moment(`${t}`,"YYYYMMDD").format("MMM Do Y")}`});